const input = $input.first().json;
const content = input && input.choices && input.choices[0]
  ? (input.choices[0].message && input.choices[0].message.content) || input.choices[0].text
  : null;
if (!content) throw new Error('DeepSeek returned no content: ' + JSON.stringify(input).slice(0, 500));
let cleaned = String(content).trim();
const fenced = cleaned.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (fenced) cleaned = fenced[1].trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  throw new Error('DeepSeek pitch response is not JSON: ' + cleaned.slice(0, 500));
}
if (!parsed.subject || !parsed.body_html) {
  throw new Error('Pitch missing required fields (subject, body_html)');
}
return {
  subject: String(parsed.subject),
  body_html: String(parsed.body_html),
  body_text: String(parsed.body_text || parsed.body_html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()),
  summary: String(parsed.summary || ''),
  audit_id: $('Webhook').first().json.body.audit_id,
  opportunity_ids: $('Webhook').first().json.body.opportunity_ids,
  generated_at: new Date().toISOString()
};
